$('inject-msg').addEventListener('click',function(e){e.stopPropagation();let v=$('review-msg').value;const k=$('review-msg-kind').value;if(k==='empty')v='';if(k==='null')v=null;if(k==='undefined')v=undefined;msgWin.show(v);});
function markShared(){const w=$('msg-win');if(w){w.dataset.componentId='CMP-03';w.dataset.uiId='UI-203';w.dataset.stateId='ST-07';w.querySelector('input[type="button"]').dataset.flowId='FLOW-14';w.querySelector('input[type="button"]').dataset.uiId='UI-205';w.firstElementChild.dataset.uiId='UI-204';w.firstElementChild.dataset.flowId='FLOW-15';}const cover=$('_frontCover');if(cover){cover.dataset.componentId='CMP-03';cover.dataset.uiId='UI-202';cover.dataset.stateId=cover.style.display==='none'?'ST-06':(Ajax.activeRequestCount>0?'ST-03':'ST-07');}}
const markSharedOriginal=markShared;markShared=function(){markSharedOriginal();const drag=document.querySelector('.common-style-5');if(drag){drag.dataset.componentId='CMP-03';drag.dataset.uiId='UI-206';drag.dataset.stateId='ST-08';}};
const commonObserver=new MutationObserver(markShared);commonObserver.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['style']});markShared();
